-- Realistic extra test questions over RAG research papers, v3 (2026-10-13): any column; most need columns outside the initial build.
-- QX1: For each application domain, how many papers use an agent and how many study multi-hop reasoning?
SELECT CASE WHEN application_domain LIKE '%Medical%' THEN 'Medical' WHEN application_domain LIKE '%Finance%' THEN 'Finance' WHEN application_domain LIKE '%Education%' THEN 'Education' WHEN application_domain LIKE '%Legal%' THEN 'Legal' ELSE 'General or other' END AS domain, COUNT(*) AS papers, SUM(CASE WHEN use_agent = 'Yes' THEN 1 ELSE 0 END) AS with_agent, SUM(CASE WHEN reasoning_depth = 'multi-hop' THEN 1 ELSE 0 END) AS multi_hop FROM cspaper GROUP BY domain;
-- QX2: Which generator model families are used by at least 3 papers, with how many baselines those papers compare on average, most used first?
SELECT CASE WHEN generator_model LIKE '%GPT%' THEN 'GPT' WHEN generator_model LIKE '%Llama%' THEN 'Llama' WHEN generator_model LIKE '%Qwen%' THEN 'Qwen' WHEN generator_model LIKE '%Mistral%' THEN 'Mistral' ELSE 'Other' END AS generator_family, COUNT(*) AS papers, AVG(baseline_amount) AS average_baselines FROM cspaper WHERE generator_model IS NOT NULL AND generator_model <> '' GROUP BY generator_family HAVING COUNT(*) >= 3 ORDER BY papers DESC, generator_family;
-- QX3: For each retrieval method, how many papers evaluate on TriviaQA, 2WikiMultihopQA and MuSiQue?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, SUM(CASE WHEN evaluation_dataset LIKE '%TriviaQA%' THEN 1 ELSE 0 END) AS on_triviaqa, SUM(CASE WHEN evaluation_dataset LIKE '%2Wiki%' THEN 1 ELSE 0 END) AS on_2wikimultihopqa, SUM(CASE WHEN evaluation_dataset LIKE '%MuSiQue%' THEN 1 ELSE 0 END) AS on_musique FROM cspaper GROUP BY retrieval_family;
-- QX4: For papers with and without a reranker, how many report F1, exact match, accuracy and ROUGE?
SELECT uses_reranker, SUM(CASE WHEN evaluation_metric LIKE '%F1%' THEN 1 ELSE 0 END) AS report_f1, SUM(CASE WHEN evaluation_metric LIKE '%EM%' OR evaluation_metric LIKE '%Exact Match%' THEN 1 ELSE 0 END) AS report_exact_match, SUM(CASE WHEN evaluation_metric LIKE '%Accuracy%' THEN 1 ELSE 0 END) AS report_accuracy, SUM(CASE WHEN evaluation_metric LIKE '%ROUGE%' THEN 1 ELSE 0 END) AS report_rouge FROM cspaper WHERE uses_reranker IN ('Yes', 'No') GROUP BY uses_reranker;
-- QX5: How many papers, and how many baselines on average, for each combination of reasoning depth and knowledge graph use?
SELECT reasoning_depth, uses_knowledge_graph, COUNT(*) AS papers, AVG(baseline_amount) AS average_baselines FROM cspaper WHERE reasoning_depth IN ('multi-hop', 'single-hop') AND uses_knowledge_graph IN ('Yes', 'No') GROUP BY reasoning_depth, uses_knowledge_graph;
-- QX6: Which three application domains with at least 5 papers have the largest share of agent papers?
SELECT CASE WHEN application_domain LIKE '%Medical%' THEN 'Medical' WHEN application_domain LIKE '%Finance%' THEN 'Finance' WHEN application_domain LIKE '%Education%' THEN 'Education' WHEN application_domain LIKE '%Legal%' THEN 'Legal' WHEN application_domain LIKE '%Academic%' THEN 'Academic' WHEN application_domain LIKE '%General%' THEN 'General' ELSE 'Other' END AS domain, COUNT(*) AS papers, AVG(CASE WHEN use_agent = 'Yes' THEN 1.0 ELSE 0.0 END) AS agent_share FROM cspaper WHERE application_domain IS NOT NULL AND application_domain <> '' GROUP BY domain HAVING COUNT(*) >= 5 ORDER BY agent_share DESC, domain LIMIT 3;
-- QX7: For each reasoning depth, how many papers compare against GPT-4 or ChatGPT as a baseline, out of how many papers?
SELECT reasoning_depth, SUM(CASE WHEN baseline LIKE '%GPT-4%' OR baseline LIKE '%ChatGPT%' THEN 1 ELSE 0 END) AS against_gpt4_or_chatgpt, COUNT(*) AS papers FROM cspaper WHERE reasoning_depth IN ('multi-hop', 'single-hop') GROUP BY reasoning_depth;
-- QX8: For each agent framework, how many papers support multi-turn retrieval and how many use a knowledge graph?
SELECT agent_framework, COUNT(*) AS papers, SUM(CASE WHEN multi_turn_retrieval = 'Yes' THEN 1 ELSE 0 END) AS multi_turn, SUM(CASE WHEN uses_knowledge_graph = 'Yes' THEN 1 ELSE 0 END) AS with_knowledge_graph FROM cspaper WHERE agent_framework IN ('CoT', 'ToT', 'Multi-Agent Collaboration', 'Other') GROUP BY agent_framework;
-- QX9: For each kind of input data, how many papers are there and how many use an agent?
SELECT CASE WHEN data_modality LIKE '%Image%' OR data_modality LIKE '%Audio%' THEN 'multimodal' WHEN data_modality LIKE '%Table%' OR data_modality LIKE '%Code%' THEN 'text with tables or code' ELSE 'text only' END AS modality, COUNT(*) AS papers, SUM(CASE WHEN use_agent = 'Yes' THEN 1 ELSE 0 END) AS with_agent FROM cspaper WHERE data_modality IS NOT NULL AND data_modality <> '' GROUP BY modality;
-- QX10: Among multi-hop papers, which retrieval methods compare against more baselines on average than papers overall?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, COUNT(*) AS papers, AVG(baseline_amount) AS average_baselines FROM cspaper WHERE reasoning_depth = 'multi-hop' GROUP BY retrieval_family HAVING AVG(baseline_amount) > (SELECT AVG(baseline_amount) FROM cspaper);
-- QX11: How many papers, and what is the largest number of baselines, for each combination of multi-turn retrieval and knowledge graph use?
SELECT multi_turn_retrieval, uses_knowledge_graph, COUNT(*) AS papers, MAX(baseline_amount) AS most_baselines FROM cspaper WHERE multi_turn_retrieval IN ('Yes', 'No') AND uses_knowledge_graph IN ('Yes', 'No') GROUP BY multi_turn_retrieval, uses_knowledge_graph;
-- QX12: For each retrieval method, how many papers evaluate on HotpotQA and how many report a HotpotQA result?
SELECT CASE WHEN retrieval_method LIKE '%Hybrid%' THEN 'Hybrid' WHEN retrieval_method LIKE '%Graph%' THEN 'Graph-based' WHEN retrieval_method LIKE '%Dense%' THEN 'Dense' WHEN retrieval_method LIKE '%Sparse%' THEN 'Sparse' WHEN retrieval_method LIKE '%Web%' THEN 'Web search' ELSE 'Other' END AS retrieval_family, SUM(CASE WHEN evaluation_dataset LIKE '%HotpotQA%' THEN 1 ELSE 0 END) AS on_hotpotqa, SUM(CASE WHEN performance_on_hotpotqa IS NOT NULL AND performance_on_hotpotqa <> '' THEN 1 ELSE 0 END) AS report_hotpotqa FROM cspaper GROUP BY retrieval_family;
